                ret.BaseScale = this.BaseScale.Combine(rhs.BaseScale);
                ret.FootWeight = this.FootWeight.Combine(rhs.FootWeight);
                ret.ImpactMaterialType = this.ImpactMaterialType.Combine(rhs.ImpactMaterialType);
                ret.SoundLevel = this.SoundLevel.Combine(rhs.SoundLevel);
                ret.InheritsSoundFrom = this.InheritsSoundFrom.Combine(rhs.InheritsSoundFrom);
                ret.SoundTypes = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, CreatureSoundType.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.SoundTypes?.Overall, rhs.SoundTypes?.Overall), Noggog.ExceptionExt.Combine(this.SoundTypes?.Specific, rhs.SoundTypes?.Specific));
                ret.ImpactDataset = this.ImpactDataset.Combine(rhs.ImpactDataset);
                ret.MeleeWeaponList = this.MeleeWeaponList.Combine(rhs.MeleeWeaponList);
                return ret;
