        public void Print(
            ICreatureGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            Creature.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"Creature =>");
            }
            else
            {
                sb.AppendLine($"{name} (Creature) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
        protected static void ToStringFields(
            ICreatureGetter item,
            StructuredStringBuilder sb,
            Creature.Mask<bool>? printMask = null)
        {
            Fallout3MajorRecordCommon.ToStringFields(
                item: item,
                sb: sb,
                printMask: printMask);
            if (printMask?.ObjectBounds?.Overall ?? true)
            {
                item.ObjectBounds?.Print(sb, "ObjectBounds");
            }
            if ((printMask?.Name ?? true)
                && item.Name is {} NameItem)
            {
                sb.AppendItem(NameItem, "Name");
            }
            if ((printMask?.Model?.Overall ?? true)
                && item.Model is {} ModelItem)
            {
                ModelItem?.Print(sb, "Model");
            }
            if (printMask?.ActorEffects?.Overall ?? true)
            {
                sb.AppendLine("ActorEffects =>");
                using (sb.Brace())
                {
                    foreach (var subItem in item.ActorEffects)
