        public static ICreatureGetter CreatureFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new CreatureBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static ICreatureGetter CreatureFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return CreatureFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Creature_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.FULL:
                {
                    _NameLocation = (stream.Position - offset);
                    return (int)Creature_FieldIndex.Name;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODB:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                case RecordTypeInts.MODD:
                {
                    this.Model = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Creature_FieldIndex.Model;
                }
                case RecordTypeInts.SPLO:
                {
                    this.ActorEffects = BinaryOverlayList.FactoryByArray<IFormLinkGetter<ISpellGetter>>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        getter: (s, p) => FormLinkBinaryTranslation.Instance.OverlayFactory<ISpellGetter>(p, s),
                        locs: ParseRecordLocations(
                            stream: stream,
                            constants: _package.MetaData.Constants.SubConstants,
                            trigger: RecordTypes.SPLO,
                            skipHeader: true,
                            translationParams: translationParams));
                    return (int)Creature_FieldIndex.ActorEffects;
                }
                case RecordTypeInts.EITM:
                {
                    _UnarmedAttackEffectLocation = (stream.Position - offset);
                    return (int)Creature_FieldIndex.UnarmedAttackEffect;
                }
                case RecordTypeInts.EAMT:
                {
                    _UnarmedAttackAnimationLocation = (stream.Position - offset);
                    return (int)Creature_FieldIndex.UnarmedAttackAnimation;
                }
                case RecordTypeInts.NIFZ:
                {
                    this.Models = BinaryOverlayList.FactoryByLazyParseWithTrigger<String>(
                        stream: stream,
                        package: _package,
                        finalPos: finalPos,
                        getter: (s, p) => BinaryStringUtility.ParseUnknownLengthString(s, encoding: p.MetaData.Encodings.NonTranslated),
                        trimNullSuffix: true);
